INSERT INTO "option_category_items" ("id", "category_id", "label", "description", "flat_price", "sort_order", "extras", "updated_at")
SELECT 'catalog-' || defaults.key || '-' || defaults.option_id, category.id, defaults.label, defaults.description,
       defaults.price, defaults.position, defaults.extras, CURRENT_TIMESTAMP
FROM (VALUES
('lyric_templates', 'wedding-song-lyrics', 'Personalized Wedding Picture Canvas Prints With Song Lyrics', 'Cherish your wedding moments with flowing romantic song lyrics softly layered over your couple portrait.', 0, 0, '{"id":"wedding-song-lyrics","name":"Personalized Wedding Picture Canvas Prints With Song Lyrics","category":"artwork","previewImage":"/assets/lyric-canvas/wedding-song-lyrics.svg","description":"Cherish your wedding moments with flowing romantic song lyrics softly layered over your couple portrait.","defaultLayout":"photo-lyrics-overlay","defaultBackground":{"color":"#FFFFFF","overlayDarkness":35},"defaultTypography":{"fontFamily":"Playfair Display","fontSize":"base","fontStyle":"normal","textColor":"#FFFFFF","alignment":"center"},"supportsPhoto":true,"defaultText":{"title":"A THOUSAND YEARS","artistOrSubtitle":"CHRISTINA PERRI","lyrics":"Heart beats fast, colors and promises\nHow to be brave? How can I love when I''m afraid to fall?\nI have died every day waiting for you\nDarling, don''t be afraid\nI have loved you for a thousand years\nI''ll love you for a thousand more","dateOrNames":"SARAH & DAVID • OCTOBER 14, 2024"},"priceAdjustment":0,"available":true,"themeNote":"Designer will harmonize typography placement with your photo composition."}'::jsonb),
('lyric_templates', 'wedding-first-dance', 'Wedding First Dance Song Lyrics', 'Capture the magic of your first dance with romantic song lyrics framed in a modern frosted plaque.', 0, 1, '{"id":"wedding-first-dance","name":"Wedding First Dance Song Lyrics","category":"artwork","previewImage":"/assets/lyric-canvas/wedding-first-dance.svg","description":"Capture the magic of your first dance with romantic song lyrics framed in a modern frosted plaque.","defaultLayout":"first-dance-card","defaultBackground":{"color":"#FFFFFF","overlayDarkness":35},"defaultTypography":{"fontFamily":"Dancing Script","fontSize":"base","fontStyle":"italic","textColor":"#FFFFFF","alignment":"center"},"supportsPhoto":true,"defaultText":{"title":"CAN''T HELP FALLING IN LOVE","artistOrSubtitle":"OUR FIRST DANCE SONG","lyrics":"Wise men say only fools rush in\nBut I can''t help falling in love with you\nLike a river flows surely to the sea\nDarling, so it goes, some things are meant to be\nTake my hand, take my whole life too\nFor I can''t help falling in love with you","dateOrNames":"EMMA & NOAH • ESTABLISHED 2024"},"priceAdjustment":0,"available":true,"themeNote":"Includes modern frosted glass card treatment over the first dance photograph."}'::jsonb),
('lyric_templates', 'wedding-vows-wall-art', 'Turn Wedding Vows into Wall Art', 'Timeless split canvas layout featuring your wedding ceremony photo paired with your personal vows.', 0, 2, '{"id":"wedding-vows-wall-art","name":"Turn Wedding Vows into Wall Art","category":"quote_art","previewImage":"/assets/lyric-canvas/wedding-vows-wall-art.svg","description":"Timeless split canvas layout featuring your wedding ceremony photo paired with your personal vows.","defaultLayout":"wedding-vows-photo","defaultBackground":{"color":"#FEFCE8","texture":"parchment","overlayDarkness":0},"defaultTypography":{"fontFamily":"Cormorant Garamond","fontSize":"base","fontStyle":"italic","textColor":"#1C1917","alignment":"center"},"supportsPhoto":true,"defaultText":{"title":"OUR SACRED WEDDING VOWS","artistOrSubtitle":"PROMISES FOR A LIFETIME","lyrics":"I take you to be my partner for life.\nTo laugh with you in joy, to comfort you in sorrow,\nTo encourage you in your dreams and cherish you through every season.\nThrough sunshine and through storm, in sickness and in health,\nAs long as we both shall live,\nMy heart is forever your home.","dateOrNames":"MICHAEL & JESSICA • JUNE 22, 2024"},"priceAdjustment":0,"available":true,"themeNote":"Displays photo on left and vows in crisp calligraphic typography on right."}'::jsonb),
('lyric_templates', 'first-marriage-anniversary', 'First Marriage Anniversary Songs on Canvas', 'Celebrate 365 days of love with your anniversary song and couple portrait in sleek editorial typography.', 0, 3, '{"id":"first-marriage-anniversary","name":"First Marriage Anniversary Songs on Canvas","category":"artwork","previewImage":"/assets/lyric-canvas/first-marriage-anniversary.svg","description":"Celebrate 365 days of love with your anniversary song and couple portrait in sleek editorial typography.","defaultLayout":"split-side-by-side","defaultBackground":{"color":"#FFFFFF","overlayDarkness":35},"defaultTypography":{"fontFamily":"Cinzel","fontSize":"base","fontStyle":"normal","textColor":"#F4F4F5","alignment":"center"},"supportsPhoto":true,"defaultText":{"title":"1ST ANNIVERSARY","artistOrSubtitle":"365 DAYS OF HAPPINESS","lyrics":"Every single day with you is a gift.\nYou are my today and all of my tomorrows.\nThrough every laughter and every journey,\nLoving you has been the easiest and most beautiful choice\nI have ever made.","dateOrNames":"SOPHIA & JAMES • ONE YEAR DOWN, FOREVER TO GO"},"priceAdjustment":0,"available":true,"themeNote":"Editorial anniversary edition with high-contrast monochrome typography."}'::jsonb),
('lyric_templates', 'personalized-wedding-gift', 'Personalized Wedding Gift Canvas Prints', 'An unforgettable gift featuring the newlyweds photo with an elegant lower-third lyric banner.', 0, 4, '{"id":"personalized-wedding-gift","name":"Personalized Wedding Gift Canvas Prints","category":"artwork","previewImage":"/assets/lyric-canvas/personalized-wedding-gift.svg","description":"An unforgettable gift featuring the newlyweds photo with an elegant lower-third lyric banner.","defaultLayout":"bottom-third-lyrics","defaultBackground":{"color":"#FFFFFF","overlayDarkness":35},"defaultTypography":{"fontFamily":"Playfair Display","fontSize":"base","fontStyle":"normal","textColor":"#FEF08A","alignment":"center"},"supportsPhoto":true,"defaultText":{"title":"ALL OF ME LOVES ALL OF YOU","artistOrSubtitle":"JOHN LEGEND","lyrics":"''Cause all of me loves all of you\nLove your curves and all your edges\nAll your perfect imperfections\nGive your all to me, I''ll give my all to you\nYou''re my end and my beginning","dateOrNames":"OLIVIA & LIAM • CELEBRATING LOVE"},"priceAdjustment":0,"available":true,"themeNote":"Full-bleed portrait photo with lower-third gold accent typography."}'::jsonb),
('lyric_templates', 'forever-young-lyrics', 'Forever Young — Song Lyrics on Canvas', 'Inspirational Bob Dylan folk classic lyrics with golden hour glow over cherished family and couple photos.', 0, 5, '{"id":"forever-young-lyrics","name":"Forever Young — Song Lyrics on Canvas","category":"artwork","previewImage":"/assets/lyric-canvas/forever-young-lyrics.svg","description":"Inspirational Bob Dylan folk classic lyrics with golden hour glow over cherished family and couple photos.","defaultLayout":"photo-lyrics-overlay","defaultBackground":{"color":"#78350F","overlayDarkness":35},"defaultTypography":{"fontFamily":"Cinzel","fontSize":"base","fontStyle":"normal","textColor":"#FFFBEB","alignment":"center"},"supportsPhoto":true,"defaultText":{"title":"FOREVER YOUNG","artistOrSubtitle":"BOB DYLAN","lyrics":"May God bless and keep you always\nMay your wishes all come true\nMay you always do for others and let others do for you\nMay you build a ladder to the stars and climb on every rung\nMay you stay forever young","dateOrNames":"BLESSINGS FOR A LIFETIME • ESTABLISHED 2024"},"priceAdjustment":0,"available":true,"themeNote":"Warm golden hues and timeless classic serif typography."}'::jsonb),
('lyric_templates', 'wedding-vows-canvas', 'Canvas Wall Art — Wedding Vows Canvas', 'Sacred wedding promises crafted in romantic cursive script with decorative double-line border detailing.', 0, 6, '{"id":"wedding-vows-canvas","name":"Canvas Wall Art — Wedding Vows Canvas","category":"quote_art","previewImage":"/assets/lyric-canvas/wedding-vows-canvas.svg","description":"Sacred wedding promises crafted in romantic cursive script with decorative double-line border detailing.","defaultLayout":"classic-centered-lyrics","defaultBackground":{"color":"#FAF5FF","overlayDarkness":0},"defaultTypography":{"fontFamily":"Dancing Script","fontSize":"lg","fontStyle":"italic","textColor":"#581C87","alignment":"center"},"supportsPhoto":true,"defaultText":{"title":"TO HAVE AND TO HOLD","artistOrSubtitle":"FROM THIS DAY FORWARD","lyrics":"From this day forward, for better, for worse,\nFor richer, for poorer, in sickness and in health,\nTo love and to cherish, till death do us part.\nI give you my hand, my heart, and my love.","dateOrNames":"ALEX & TAYLOR • OUR SACRED PROMISE"},"priceAdjustment":0,"available":true,"themeNote":"Clean botanical and vows typography on canvas."}'::jsonb),
('lyric_templates', 'sheet-music-wall-art', 'Sheet Music Canvas Print — Wall Art', 'Vintage stave, clef and musical notes canvas background paired with your song title, couple names, and lyrics.', 0, 7, '{"id":"sheet-music-wall-art","name":"Sheet Music Canvas Print — Wall Art","category":"sheet_music","previewImage":"/assets/lyric-canvas/sheet-music-wall-art.svg","description":"Vintage stave, clef and musical notes canvas background paired with your song title, couple names, and lyrics.","defaultLayout":"sheet-music-bg","defaultBackground":{"color":"#FEF9C3","texture":"sheet-music","overlayDarkness":0},"defaultTypography":{"fontFamily":"Cinzel","fontSize":"base","fontStyle":"normal","textColor":"#78350F","alignment":"center"},"supportsPhoto":true,"defaultText":{"title":"CANON IN D MAJOR","artistOrSubtitle":"OUR SONG WRITTEN IN THE STARS","lyrics":"Music gives a soul to the universe,\nWings to the mind, flight to the imagination,\nAnd life to everything.\nOur song will play on in our hearts forever.","dateOrNames":"SARAH & LUCAS • FIRST DANCE SCORE"},"priceAdjustment":0,"available":true,"themeNote":"Features authentic vintage sheet music stave illustration."}'::jsonb),
('lyric_templates', 'first-anniversary-gift', 'First Wedding Anniversary Gift', 'Statement quote design with large decorative quotation marks on blush canvas for him or her.', 0, 8, '{"id":"first-anniversary-gift","name":"First Wedding Anniversary Gift","category":"quote_art","previewImage":"/assets/lyric-canvas/first-anniversary-gift.svg","description":"Statement quote design with large decorative quotation marks on blush canvas for him or her.","defaultLayout":"quote-solid-bg","defaultBackground":{"color":"#FCE7F3","overlayDarkness":0},"defaultTypography":{"fontFamily":"Playfair Display","fontSize":"base","fontStyle":"normal","textColor":"#831843","alignment":"center"},"supportsPhoto":true,"defaultText":{"title":"1ST ANNIVERSARY FOR HIM & HER","artistOrSubtitle":"365 DAYS OF UNCONDITIONAL LOVE","lyrics":"Love is a partnership of two people who bring out\nthe very best in each other.\nThank you for 365 days of smiles,\nlaughter, and endless love.","dateOrNames":"HAPPY 1ST ANNIVERSARY • TO MY FOREVER"},"priceAdjustment":0,"available":true,"themeNote":"Typographic quote style with optional photo background."}'::jsonb),
('lyric_templates', 'couples-personalized-art', 'Personalized Canvas Art Couples Gifts', 'Split modern layout pairing your favorite couple snapshot with a sweet song lyric and heart emblem.', 0, 9, '{"id":"couples-personalized-art","name":"Personalized Canvas Art Couples Gifts","category":"artwork","previewImage":"/assets/lyric-canvas/couples-personalized-art.svg","description":"Split modern layout pairing your favorite couple snapshot with a sweet song lyric and heart emblem.","defaultLayout":"split-side-by-side","defaultBackground":{"color":"#FEF9C3","overlayDarkness":0},"defaultTypography":{"fontFamily":"Dancing Script","fontSize":"base","fontStyle":"italic","textColor":"#854D0E","alignment":"center"},"supportsPhoto":true,"defaultText":{"title":"BETTER TOGETHER","artistOrSubtitle":"JACK JOHNSON","lyrics":"It''s always better when we''re together.\nWe''ll look at the stars when we''re together,\nWell, it''s always better when we''re together.","dateOrNames":"JACK & CHLOE • TOGETHER IS OUR FAVORITE PLACE"},"priceAdjustment":0,"available":true,"themeNote":"Cozy split canvas with hand-drawn red heart motif."}'::jsonb),
('lyric_templates', 'first-dance-lyrics', 'First Dance Canvas — Your Wedding Song Lyrics on Canvas', 'Large calligraphic "Love" headline with biblical 1 Corinthians love poem or your wedding song lyrics.', 0, 10, '{"id":"first-dance-lyrics","name":"First Dance Canvas — Your Wedding Song Lyrics on Canvas","category":"quote_art","previewImage":"/assets/lyric-canvas/first-dance-lyrics.svg","description":"Large calligraphic \"Love\" headline with biblical 1 Corinthians love poem or your wedding song lyrics.","defaultLayout":"classic-centered-lyrics","defaultBackground":{"color":"#FEFCE8","texture":"parchment","overlayDarkness":0},"defaultTypography":{"fontFamily":"Cormorant Garamond","fontSize":"base","fontStyle":"italic","textColor":"#78350F","alignment":"center"},"supportsPhoto":true,"defaultText":{"title":"LOVE NEVER FAILS","artistOrSubtitle":"1 CORINTHIANS 13:4-8","lyrics":"Love is patient, love is kind.\nIt does not envy, it does not boast.\nIt always protects, always trusts,\nAlways hopes, always perseveres.\nLove never fails.","dateOrNames":"DANIEL & CHARLOTTE • FIRST DANCE MEMORIES"},"priceAdjustment":0,"available":true,"themeNote":"Classic script \"Love\" header on gallery-wrapped canvas."}'::jsonb),
('lyric_templates', 'wedding-vows-1st-anniversary', 'Wedding Vows on Canvas — Anniversary Gift', 'Golden hour sunset couple photo with anniversary vow renewal typography along the lower third.', 0, 11, '{"id":"wedding-vows-1st-anniversary","name":"Wedding Vows on Canvas — Anniversary Gift","category":"quote_art","previewImage":"/assets/lyric-canvas/wedding-vows-1st-anniversary.svg","description":"Golden hour sunset couple photo with anniversary vow renewal typography along the lower third.","defaultLayout":"bottom-third-lyrics","defaultBackground":{"color":"#FFFFFF","overlayDarkness":35},"defaultTypography":{"fontFamily":"Dancing Script","fontSize":"base","fontStyle":"italic","textColor":"#FEF08A","alignment":"center"},"supportsPhoto":true,"defaultText":{"title":"I CHOOSE YOU OVER AND OVER AGAIN","artistOrSubtitle":"1ST ANNIVERSARY VOW RENEWAL","lyrics":"Without pause, without a doubt, in a heartbeat.\nThrough every laughter and every trial,\nI''ll keep choosing you.\nToday, tomorrow, and for all the days to come.","dateOrNames":"ONE YEAR OF HAPPINESS • FOREVER TO GO"},"priceAdjustment":0,"available":true,"themeNote":"Sunset romantic atmosphere with vow renewal dedication."}'::jsonb),
('lyric_sizes', 'lyric-8x8', 'Lyric Canvas: 8" × 8"', NULL, 1498.5, 0, '{"id":"lyric-8x8","productTypeId":"canvas-lyric","label":"Lyric Canvas: 8\" × 8\"","dimensionsSummary":"8\" × 8\"","price":1498.5,"widthInches":8,"heightInches":8,"categories":["RECOMMENDED","SQUARE","SMALL"],"panels":[{"id":"p0","label":"Lyric Canvas","dimension":"8\" × 8\"","widthRatio":8,"heightRatio":8}]}'::jsonb),
