('pop_art_styles', 'andy-warhol', 'Andy-Warhol', 'Iconic 4-quadrant screenprint Pop Art with contrasting vibrant pop palettes across four quadrants.', 0, 0, '{"id":"andy-warhol","name":"Andy-Warhol","previewImage":"/assets/pop-art/andy-warhol.svg","price":499,"priceAdjustment":0,"description":"Iconic 4-quadrant screenprint Pop Art with contrasting vibrant pop palettes across four quadrants.","processingType":"multi-panel-warhol","processingNote":"4-panel Pop Art composition with contrasting complementary background and subject color treatments.","panelsCount":4,"availability":"available","badge":"POPULAR"}'::jsonb),
('pop_art_styles', 'caricatures', 'Caricatures', 'Playful cartoon caricature styling with bold hand-drawn contours, comic cel shading, and warm tones.', 100, 1, '{"id":"caricatures","name":"Caricatures","previewImage":"/assets/pop-art/caricatures.svg","price":599,"priceAdjustment":100,"description":"Playful cartoon caricature styling with bold hand-drawn contours, comic cel shading, and warm tones.","processingType":"caricature","processingNote":"Artistic caricature preview generated. Our digital artists hand-refine the exaggerated features and proportions for your final print.","panelsCount":1,"availability":"available","badge":"ARTIST PICK"}'::jsonb),
('pop_art_styles', 'pixel-painting', 'Pixel Painting', 'Retro 8-bit digital pixel art mosaic transformation preserving facial likeness with sharp mosaic tiles.', 1251, 2, '{"id":"pixel-painting","name":"Pixel Painting","previewImage":"/assets/pop-art/pixel-painting.svg","price":1750,"priceAdjustment":1251,"description":"Retro 8-bit digital pixel art mosaic transformation preserving facial likeness with sharp mosaic tiles.","processingType":"pixel-mosaic","processingNote":"Genuine digital pixel art mosaic transformation with calibrated block resolution and pixel grid geometry.","panelsCount":1,"availability":"available","badge":"PREMIUM"}'::jsonb),
('pop_art_styles', 'lichtenstein', 'Lichtenstein', 'Roy Lichtenstein comic strip pop art featuring Ben-Day halftone dots, ink contours, and primary comic colors.', 0, 3, '{"id":"lichtenstein","name":"Lichtenstein","previewImage":"/assets/pop-art/lichtenstein.svg","price":499,"priceAdjustment":0,"description":"Roy Lichtenstein comic strip pop art featuring Ben-Day halftone dots, ink contours, and primary comic colors.","processingType":"halftone-comic","processingNote":"Comic-book Ben-Day halftone dot pattern rasterization with bold black inking and high-contrast color separation.","panelsCount":1,"availability":"available"}'::jsonb),
('pop_art_styles', 'glo-portrait', 'Glo-Portrait', 'Vibrant neon glowing portrait with electric contours on a bright pop art textured backdrop.', 0, 4, '{"id":"glo-portrait","name":"Glo-Portrait","previewImage":"/assets/pop-art/glo-portrait.svg","price":499,"priceAdjustment":0,"description":"Vibrant neon glowing portrait with electric contours on a bright pop art textured backdrop.","processingType":"neon-glow","processingNote":"Electric neon edge luminescence with saturated pop duotone color mapping and pattern background.","panelsCount":1,"availability":"available"}'::jsonb),
('pop_art_styles', 'coca-cola1', 'Coca Cola1', '1960s advertising pop art screenprint in bold magenta, hot pink, and crisp cyan highlights.', 0, 5, '{"id":"coca-cola1","name":"Coca Cola1","previewImage":"/assets/pop-art/coca-cola1.svg","price":499,"priceAdjustment":0,"description":"1960s advertising pop art screenprint in bold magenta, hot pink, and crisp cyan highlights.","processingType":"poster-tritone","processingNote":"High-contrast 60s vintage silkscreen tri-tone posterization in vibrant fuchsia and electric cyan.","panelsCount":1,"availability":"available"}'::jsonb),
('pop_art_styles', 'coca-cola2', 'Coca Cola2', 'Rich vintage poster style featuring crimson red, antique off-white cream, and deep midnight navy.', 0, 6, '{"id":"coca-cola2","name":"Coca Cola2","previewImage":"/assets/pop-art/coca-cola2.svg","price":499,"priceAdjustment":0,"description":"Rich vintage poster style featuring crimson red, antique off-white cream, and deep midnight navy.","processingType":"poster-tritone","processingNote":"Vintage high-contrast posterization in crimson red, warm parchment cream, and midnight navy.","panelsCount":1,"availability":"available"}'::jsonb),
('pop_art_styles', 'che-all-in-1', 'Che-all-in-1', 'Iconic 4-panel revolutionary pop art montage with rotating bold graphic screenprint colorways.', 0, 7, '{"id":"che-all-in-1","name":"Che-all-in-1","previewImage":"/assets/pop-art/che-all-in-1.svg","price":499,"priceAdjustment":0,"description":"Iconic 4-panel revolutionary pop art montage with rotating bold graphic screenprint colorways.","processingType":"multi-panel-warhol","processingNote":"4-panel high-contrast screenprint arrangement featuring bold red, amber, cyan, and magenta duotones.","panelsCount":4,"availability":"available"}'::jsonb),
('pop_art_styles', 'che-all-in-2', 'Che-all-in-2', 'Dynamic 6-panel high-impact pop art montage with rotating vibrant silkscreen duotone treatments.', 0, 8, '{"id":"che-all-in-2","name":"Che-all-in-2","previewImage":"/assets/pop-art/che-all-in-2.svg","price":499,"priceAdjustment":0,"description":"Dynamic 6-panel high-impact pop art montage with rotating vibrant silkscreen duotone treatments.","processingType":"multi-panel-warhol","processingNote":"6-panel screenprint montage cycling through red, gold, green, cyan, violet, and amber pop blocks.","panelsCount":6,"availability":"available"}'::jsonb),
('pop_art_styles', 'coupe5', 'Coupe5', 'High-contrast silver gelatin black-and-white pop portrait with rich velvety blacks and bright highlights.', 0, 9, '{"id":"coupe5","name":"Coupe5","previewImage":"/assets/pop-art/coupe5.svg","price":499,"priceAdjustment":0,"description":"High-contrast silver gelatin black-and-white pop portrait with rich velvety blacks and bright highlights.","processingType":"monochrome-high-contrast","processingNote":"Classic fine-art black-and-white pop posterization with stark tonal separation and deep contrast.","panelsCount":1,"availability":"available"}'::jsonb),
('pop_art_styles', 'coupe8', 'Coupe8', 'Warm monochrome sepia-tinted vintage screenprint with deep espresso shadows and cream highlights.', 0, 10, '{"id":"coupe8","name":"Coupe8","previewImage":"/assets/pop-art/coupe8.svg","price":499,"priceAdjustment":0,"description":"Warm monochrome sepia-tinted vintage screenprint with deep espresso shadows and cream highlights.","processingType":"poster-duotone","processingNote":"Warm sepia vintage duotone screenprint with filmic tonal gradation and rich midtone warmth.","panelsCount":1,"availability":"available"}'::jsonb),
