JOIN "option_categories" AS category ON category."baseKey" = defaults.key AND category."material_scope" = 'BOTH'
WHERE NOT EXISTS (
  SELECT 1 FROM "option_category_items" AS item
  WHERE item.category_id = category.id AND item.extras->>'id' = defaults.option_id
)
ON CONFLICT ("id") DO NOTHING;

-- Install the existing Backgrounds and Finish options for fresh deployments.
INSERT INTO "option_categories" ("id", "baseKey", "name", "updated_at") VALUES ('catalog-backgrounds', 'backgrounds', 'Backgrounds', CURRENT_TIMESTAMP) ON CONFLICT ("baseKey", "material_scope") DO NOTHING;
INSERT INTO "option_category_items" ("id", "category_id", "label", "description", "flat_price", "sort_order", "extras", "updated_at")
SELECT 'catalog-backgrounds-transparent', category.id, 'Transparent (Clear Optical)', NULL, 0, 0, '{"id":"transparent","hex":"transparent"}'::jsonb, CURRENT_TIMESTAMP
FROM "option_categories" AS category WHERE category."baseKey" = 'backgrounds' AND category."material_scope" = 'BOTH'
AND NOT EXISTS (SELECT 1 FROM "option_category_items" item WHERE item.category_id = category.id AND item.extras->>'id' = 'transparent') ON CONFLICT ("id") DO NOTHING;
