INSERT INTO "permissions" ("id", "key") VALUES
('catalog-permission-pricing.view', 'pricing.view'),
('catalog-permission-pricing.manage', 'pricing.manage'),
('catalog-permission-option_catalog.view', 'option_catalog.view'),
('catalog-permission-option_catalog.manage', 'option_catalog.manage'),
('catalog-permission-size_presets.view', 'size_presets.view'),
('catalog-permission-size_presets.manage', 'size_presets.manage')
ON CONFLICT ("key") DO NOTHING;

INSERT INTO "role_permissions" ("role_id", "permission_id")
SELECT roles.id, permissions.id FROM "roles" CROSS JOIN "permissions"
WHERE roles.name = 'Super Admin' AND permissions.key IN ('pricing.view', 'pricing.manage', 'option_catalog.view', 'option_catalog.manage', 'size_presets.view', 'size_presets.manage')
ON CONFLICT DO NOTHING;
